/** A position within a single line of the document, used by the parsers. */
export class Cursor {
  constructor(line, lineNo) {
    this.line = line
    this.lineNo = lineNo
    this.i = 0
  }

  peek() {
    return this.i < this.line.length ? this.line[this.i] : undefined
  }

  next() {
    return this.line[this.i++]
  }

  atEnd() {
    return this.i >= this.line.length
  }

  skipWs() {
    while (this.peek() === ' ' || this.peek() === '\t') this.i++
  }

  err(reason) {
    return new ParseError(this.lineNo, reason)
  }
}

/** Consumes `ch`, or throws `msg` when the next character is not `ch`. */
export function expectChar(cur, ch, msg) {
  if (cur.peek() !== ch) throw cur.err(msg)
  cur.next()
}

/** After a value or header, only whitespace and a comment may follow. */
export function checkTrailing(cur, msg) {
  cur.skipWs()
  const c = cur.peek()
  if (c === undefined || c === '#' || c === ';') return
  throw cur.err(msg)
}
"}

