import { makeTable, assignDotted } from './table.js'

const INTEGER_RE = /^[+-]?\d+(_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

function classifyBareword(cur, s) {
  if (s === 'true') return { kind: 'boolean', value: true }
  if (s === 'false') return { kind: 'boolean', value: false }
  if (INTEGER_RE.test(s)) {
    const digits = s.replace(/_/g, '').replace(/^\+/, '')
    return { kind: 'integer', value: BigInt(digits) }
  }
  if (FLOAT_RE.test(s) && /[.eE]/.test(s)) {
    return { kind: 'float', value: Number(s.replace(/_/g, '')) }
  }
  throw cur.err('invalid value ' + s)
}

/** Parses one value: scalar, string, array, or inline table. */
export function parseValue(cur) {
  cur.skipWs()
  const ch = cur.peek()
  if (ch === undefined || ch === ',' || ch === ']' || ch === '}') throw cur.err('expected a value')
  if (ch === '"') return { kind: 'string', value: parseBasicString(cur) }
  if (ch === "'") return { kind: 'string', value: parseLiteralString(cur) }
  if (ch === '[') return parseArrayValue(cur)
  if (ch === '{') return parseInlineTable(cur)

  let s = ''
  for (;;) {
    const c = cur.peek()
    if (c === undefined || c === ' ' || c === '\t' || c === ',' || c === ']' || c === '}') break
    s += c
    cur.next()
  }
  return classifyBareword(cur, s)
}

function parseArrayValue(cur) {
  cur.next() // opening [
  const items = []
  cur.skipWs()
  if (cur.peek() === ']') {
    cur.next()
    return { kind: 'array', items }
  }
  for (;;) {
    items.push(parseValue(cur))
    cur.skipWs()
    const c = cur.peek()
    if (c === ',') {
      cur.next()
      cur.skipWs()
      if (cur.peek() === ']') {
        cur.next()
        break
      }
      continue
    }
    if (c === ']') {
      cur.next()
      break
    }
    throw cur.err('unterminated array')
  }
  return { kind: 'array', items }
}

function parseInlineTable(cur) {
  cur.next() // opening {
