/** Creates a fresh table node at the given path from the document root. */
export function makeTable(path) {
  return { kind: 'table', entries: new Map(), headerDeclared: false, path }
}

/**
 * Walks all but the last segment of a dotted name from `startPath`/`root`,
 * creating tables as needed, and using an array of tables' last element when
 * a segment holds one. Returns the container reached and the path so far.
 */
function walkIntermediate(container, path, segments, lineNo) {
  for (let i = 0; i < segments.length - 1; i++) {
    const name = segments[i]
    path = [...path, name]
    const existing = container.entries.get(name)
    if (existing === undefined) {
      const t = makeTable(path)
      container.entries.set(name, t)
      container = t
    } else if (existing.kind === 'table') {
      container = existing
    } else if (existing.kind === 'array-of-tables') {
      container = existing.items[existing.items.length - 1]
    } else {
      throw new ParseError(lineNo, path.join('.') + ' is not a table')
    }
  }
  return { container, path }
}

/** Assigns `value` at `segments` within `table`, creating tables the dots walk through. */
export function assignDotted(table, segments, value, lineNo) {
  const { container, path } = walkIntermediate(table, table.path, segments, lineNo)
  const last = segments[segments.length - 1]
  const fullPath = [...path, last]
  if (container.entries.has(last)) {
    throw new ParseError(lineNo, 'key ' + fullPath.join('.') + ' is defined twice')
  }
  if (value.kind === 'table' || value.kind === 'array-of-tables') value.path = fullPath
  container.entries.set(last, value)
}

/** Resolves a `[name]` header, creating and marking the current table. */
export function resolveTableHeader(root, segments, lineNo) {
  const { container, path } = walkIntermediate(root, [], segments, lineNo)
  const last = segments[segments.length - 1]
  const fullPath = [...path, last]
  const existing = container.entries.get(last)
  if (existing === undefined) {
    const t = makeTable(fullPath)
    t.headerDeclared = true
    container.entries.set(last, t)
    return t
  }
  if (existing.kind === 'table') {
    if (existing.headerDeclared) {
      throw new ParseError(lineNo, 'table ' + fullPath.join('.') + ' is defined twice')
    }
    existing.headerDeclared = true
    return existing
  }
  throw new ParseError(lineNo, fullPath.join('.') + ' is not a table')
