/** Renders a document as JSON, indented by two spaces, keys in code point order. */
export function toJson(node) {
  return render(node, 0) + '\n'
}

function render(node, level) {
  switch (node.kind) {
    case 'table':
      return renderObject(sortedKeys(node).map((k) => [k, node.entries.get(k)]), level)
    case 'array-of-tables':
    case 'array':
      return renderArray(node.items, level)
    case 'string':
      return JSON.stringify(node.value)
    case 'boolean':
      return String(node.value)
    case 'integer':
      return node.value.toString()
    case 'float':
      return JSON.stringify(node.value)
    default:
      throw new Error('unreachable kind ' + node.kind)
  }
}

function renderObject(pairs, level) {
  if (pairs.length === 0) return '{}'
  const inner = '  '.repeat(level + 1)
  const outer = '  '.repeat(level)
  const body = pairs
    .map(([k, v]) => `${inner}${JSON.stringify(k)}: ${render(v, level + 1)}`)
    .join(',\n')
  return `{\n${body}\n${outer}}`
}

function renderArray(items, level) {
  if (items.length === 0) return '[]'
  const inner = '  '.repeat(level + 1)
  const outer = '  '.repeat(level)
  const body = items.map((v) => `${inner}${render(v, level + 1)}`).join(',\n')
  return `[\n${body}\n${outer}]`
}
"}

