/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { parseDocument } from './parser.js'
import { toJson } from './json-print.js'
import { toKeys } from './keys-print.js'
import { ParseError } from './errors.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (c) => chunks.push(c))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function fail(message, code) {
  process.stderr.write(message + '\n', () => process.exitCode = code)
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
    fail('error: usage: cli.js json|keys', 2)
    return
  }
  const mode = args[0]

  const text = await readStdin()

  let root
  try {
    root = parseDocument(text)
  } catch (e) {
    if (e instanceof ParseError) {
      fail(`error: ${e.message}`, 2)
      return
    }
    throw e
  }

  const output = mode === 'json' ? toJson(root) : toKeys(root)
  process.stdout.write(output, () => process.exitCode = 0)
}

main().catch((e) => {
  process.stderr.write('error: ' + (e && e.message ? e.message : String(e)) + '\n')
  process.exitCode = 2
})
"}

